"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'High Noon at the frontier town of Hope', 'author': 'Signature original', 'genre': 'Frontier Justice', 'chapters': [{'n': 1, 'title': 'Dust on the Wind', 'text': "But a branding iron changed everything. When Tom Beckett showed it — a branding iron, genuine, legal, undeniable — the room went quiet. It was proof. Proof that the outlaw Black Bart's claim was a lie, and lies, in the frontier town of Hope, have a short life.\n\nTom Beckett rode into the frontier town of Hope at sundown, with a branding iron in the saddlebag and dust in every seam. The town had the feel of a held breath — and the reason was posted on every wall: the outlaw Black Bart's notice, claiming the valley.\n\nthe telegraph operator was the first to offer a meal and the news. 'the outlaw Black Bart means to take it all,' the telegraph operator said. 'The water, the grazing, the town. Unless somebody stands up.' Tom Beckett ate slowly. Standing up was a habit."}, {'n': 2, 'title': 'The Claim', 'text': "the outlaw Black Bart came at noon, as villains do, with lawyers and gunmen in equal number. 'a branding iron is a forgery,' the outlaw Black Bart declared. 'And forgers hang.' The town watched from windows. the frontier town of Hope held its breath again.\n\nThursday night they came with fire. The livery burned, and a branding iron's copies with it — but Tom Beckett had the original where fire couldn't reach. the outlaw Black Bart had played the last card. Friday would tell.\n\nThe judge — the outlaw Black Bart's judge — set a hearing for Friday. Three days to prove a branding iron real, with the outlaw Black Bart's men watching every step. Tom Beckett smiled the thin smile of someone holding four aces."}, {'n': 3, 'title': 'High Noon', 'text': "the outlaw Black Bart's claim died that afternoon, in public, on the record. the frontier town of Hope exhaled. the telegraph operator bought the drinks. Tom Beckett drank one, slow, tasting justice. It tasted like dust and sweet water.\n\nThe hearing went ahead anyway, because Tom Beckett insisted on it. Law, not guns. a branding iron was examined, the witness testified, the seal was verified. The judge — even the outlaw Black Bart's judge — couldn't lie with the whole town watching.\n\nthe outlaw Black Bart stepped out with two gunmen. 'Last chance,' the outlaw Black Bart said. 'Ride out.' Tom Beckett thought of the frontier town of Hope, of the telegraph operator, of every small place that ever needed one person to stand. 'No,' Tom Beckett said."}, {'n': 4, 'title': 'The Drive', 'text': "They reached the railhead with the herds and the deed and their heads high. the frontier town of Hope was solvent. the frontier town of Hope was free. Tom Beckett looked back at the dust of the trail and felt the peculiar ache of a job done.\n\nthe outlaw Black Bart's rustlers hit them at the canyon — the last play of a losing hand. The fight was short and decisive: the town rode together, and together is a word the outlaw Black Bart never understood.\n\nThe hanging tested them: stampede at midnight, Tom Beckett riding the point with a lantern and a prayer; the river crossing, the telegraph operator swimming the lead steer; the long dry stretch, sharing the last canteen."}, {'n': 5, 'title': 'Home Range', 'text': "the outlaw Black Bart was last seen heading east, smaller in the distance. the frontier town of Hope didn't gloat. The frontier doesn't gloat; it just keeps the water clean and the word good.\n\na branding iron stayed in the courthouse, under glass, with the iron likeness beside it. Proof. Promise. justice rides slow but sure — carved, at the telegraph operator's insistence, on the frame.\n\nthe frontier town of Hope threw a dance. the telegraph operator danced every dance. The schoolteacher cried. The blacksmith forged a branding iron's likeness in iron for the courthouse wall — 'so nobody forgets,' he said."}, {'n': 6, 'title': 'Sundown', 'text': "Spring came, and Tom Beckett rode out with the thaw, a branding iron's story told and retold in the saloon. the telegraph operator watched them go from the porch, and didn't wave — waving is for endings, and this wasn't one.\n\nthe frontier town of Hope is still there, in the valley, under the big sky. The water runs. The cattle graze. The deed holds. Travelers ask about the iron a branding iron in the courthouse, and the old-timers tell it true.\n\njustice rides slow but sure. In the frontier town of Hope, on the trail, at sundown and sunup. The west remembers."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

